import{z as i,x as s,o as t,c as p,q as l,j as r,D as a,d as e,s as o,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"蒙特卡洛策略评估","description":"","frontmatter":{"title":"蒙特卡洛策略评估","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/monte-carlo-evaluation.md","filePath":"llm/monte-carlo-evaluation.md","lastUpdated":1791063341000}'),m={name:"llm/monte-carlo-evaluation.md"};function d(_,E,C,u,D,h){const B=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=l('<h1 id="蒙特卡洛策略评估" tabindex="-1">蒙特卡洛策略评估 <a class="header-anchor" href="#蒙特卡洛策略评估" aria-label="Permalink to &quot;蒙特卡洛策略评估&quot;">​</a></h1><div class="epigraph"><p>无模型评估的入场券是把回合跑完：均值无偏，方差却把整条余下轨迹的随机性折进一个标量。</p><footer>—— 据 Sutton &amp; Barto, Reinforcement Learning: An Introduction, 2018, 第 5 章整理</footer></div><p><a href="/llm/exploration-epsilon">上一课</a>把探索-利用权衡钉在动作选择上：ε-贪婪保证每个动作被反复访问，乐观初始化把「没试过」翻译成「先试试」，与 LLM 采样温度的对照说明温度只是全局缩放，不是探索的完整答案。但那一课有个未兑现的假设：价值 \\(v_\\pi\\) 已知。<a href="/llm/value-policy-iteration">值迭代</a>算 \\(v_\\pi\\) 靠贝尔曼方程与转移模型，而那课的结尾已经交代：「模型已知」在 LLM 里几乎不成立——环境就是模型自己，没人给你转移概率。模型未知时，评估只能从数据里来。本课写蒙特卡洛策略评估：用完整回合的经验回报平均，替代 \\(r+\\gamma Pv\\) 的模型算式。后面的 TD(0)、SARSA 与 Q 学习，都默认你已经会分「首次访问」与「每次访问」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口是：策略 \\(\\pi\\) 固定，转移与奖励未知，只要 \\(v_\\pi\\)。回报沿用<a href="/llm/return-discounting">回报、折扣与价值函数</a>的定义：\\(G_t=\\sum_{k\\ge0}\\gamma^k r_{t+k}\\)。数据形态是回合 \\(\\tau=(s_0,a_0,r_0,\\dots,s_T)\\)。动态规划的评估算子每一步都要模型；现在唯一的原料是采样出的轨迹，而 \\(v_\\pi(s)=\\mathbb{E}_\\pi[G_t\\mid s_t=s]\\) 本来就是期望。蒙特卡洛的赌注只有一条：期望可以用样本均值来估，不需要模型。<span class="marginnote">直觉类比：想知道一枚不规则硬币正面朝上的概率，你不需要研究硬币的材质和空气动力学（模型），只需要反复抛、记下正面次数除以总次数。蒙特卡洛评估就是把「某个状态好不好」变成「从那里出发跑很多次，把回报平均一下」——频率代替概率，样本均值代替期望。</span></p><h3 id="首次访问与每次访问" tabindex="-1">首次访问与每次访问 <a class="header-anchor" href="#首次访问与每次访问" aria-label="Permalink to &quot;首次访问与每次访问&quot;">​</a></h3><p>跑 \\(N\\) 条回合，每条从起点走到终止，沿途在每个状态记下从那里起算的回报 \\(G_t\\)。记账法有两种：<strong>首次访问</strong>只在本回合第一次见到 \\(s\\) 时把 \\(G_t\\) 记入样本池；<strong>每次访问</strong>每次路过都记。增量形式 \\(V(s)\\leftarrow V(s)+\\alpha\\,(G_t-V(s))\\) 把均值变成在线更新。首次访问的样本彼此独立，估计无偏；每次访问的样本共享同一条回合，有偏但一致性仍在，样本紧张时更省。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计量的构造只有三条规则。其一，回报在回合内回溯累加：从终止态倒着算 \\(G\\)，一条轨迹一遍扫描就得到全部时点的目标，不需要为每个 \\((t,s)\\) 单独重算。其二，样本池按状态分桶、按选定口径入账：首次访问口径下每回合至多为 \\(s\\) 贡献一个样本，每次访问口径下贡献多次；口径在实验开始前钉死，中途切换会把两种估计量的偏差混在一起。其三，更新用固定步长或 \\(\x07lpha=1/N(s)\\) 的递减步长：递减到无穷才收敛到真值，固定步长则刻意保留适应性——非平稳环境里这是特性，评估平稳策略时是偏差来源。</p><p>跑 \\(N\\) 条回合，每条从起点走到终止，沿途在每个状态记下从那里起算的回报 \\(G_t\\)。</p>',10)),(t(),r(n,null,{default:a(()=>[o(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EP%5B%22%E9%87%87%E6%A0%B7%E5%AE%8C%E6%95%B4%E5%9B%9E%E5%90%88%20%CF%84%22%5D%20--%3E%20SCAN%5B%22%E6%B2%BF%E8%BD%A8%E8%BF%B9%E9%80%90%E7%8A%B6%E6%80%81%E6%89%AB%E6%8F%8F%22%5D%0A%20%20SCAN%20--%3E%20FIRST%7B%22%E9%A6%96%E6%AC%A1%E8%AE%BF%E9%97%AE%E5%8F%A3%E5%BE%84%EF%BC%9A%E6%9C%AC%E5%9B%9E%E5%90%88%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%A7%81%E5%88%B0%20s%3F%22%7D%0A%20%20FIRST%20--%3E%7C%E6%98%AF%7C%20REC%5B%22%E6%8A%8A%20G_t%20%E8%AE%B0%E5%85%A5%20s%20%E7%9A%84%E6%A0%B7%E6%9C%AC%E6%B1%A0%22%5D%0A%20%20FIRST%20--%3E%7C%E5%90%A6%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%22%5D%0A%20%20REC%20--%3E%20AVG%5B%22V(s)%20%E5%90%91%E6%A0%B7%E6%9C%AC%E5%9D%87%E5%80%BC%E9%80%BC%E8%BF%91%22%5D%0A%20%20EP%20--%3E%20ENDQ%7B%22%E5%9B%9E%E5%90%88%E7%BB%93%E6%9D%9F%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20ENDQ%20--%3E%7C%E5%90%A6%7C%20WAIT%5B%22%E4%B8%8D%E6%9B%B4%E6%96%B0%EF%BC%9AG_t%20%E5%B0%9A%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"无偏的来源：首次访问的 \\(G_t\\) 是 \\(v_\\pi(s)\\) 的独立同分布样本，大数定律接管收敛。高方差的来源：\\(G_t\\) 把余下整条轨迹的随机性——每步动作抽样、每次转移、奖励噪声——折进一个数，方差随「从 \\(s\\) 到大结局」的期望长度增长。等回合的来源：\\(G_t\\) 的定义就要到 \\(r_T\\) 为止的每一项，中途缺一项就没有目标。三件事同源：不拆回合，就不拆方差，也不免等待。",-1)),(t(),r(n,null,{default:a(()=>[o(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E4%BC%B0%20v(s)%EF%BC%9A%E4%BB%8E%20s%20%E5%87%BA%E5%8F%91%E8%83%BD%E6%8B%BF%E5%A4%9A%E5%B0%91%E5%9B%9E%E6%8A%A5%22%5D%20--%3E%20A%5B%22%E5%8A%A8%E6%80%81%E8%A7%84%E5%88%92%EF%BC%9A%E9%9C%80%E8%A6%81%E8%BD%AC%E7%A7%BB%E6%A8%A1%E5%9E%8B%20P%20%E4%B8%8E%E5%A5%96%E5%8A%B1%20r%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%EF%BC%9A%E5%8F%AA%E8%A6%81%E8%B7%91%E5%AE%8C%E6%95%B4%E6%9D%A1%E5%9B%9E%E5%90%88%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%AF%8F%E6%AD%A5%E8%87%AA%E4%B8%BE%20%E7%94%A8%20v%20%E7%9A%84%E5%BD%93%E5%89%8D%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%BF%AB%20%E4%BD%86%E8%AF%AF%E5%B7%AE%E6%B2%BF%E9%93%BE%E4%BC%A0%E6%92%AD%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E7%9B%AE%E6%A0%87%E5%B0%B1%E6%98%AF%E5%AE%8C%E6%95%B4%E7%9C%9F%E5%AE%9E%E5%9B%9E%E6%8A%A5%20G_t%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E6%97%A0%E5%81%8F%20%E4%BD%86%E6%96%B9%E5%B7%AE%E5%A4%A7%20%E5%BF%85%E9%A1%BB%E7%AD%89%E5%88%B0%E5%A4%A7%E7%BB%93%E5%B1%80%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">\\(\\gamma=0.99\\) 的有效视界约 \\(1/(1-\\gamma)=100\\) 步；一条一千 token 的生成把上千次抽样噪声折进一个标量，样本之间还不独立——「无偏」不等于「准」。Sutton &amp; Barto 2018 §5.1 只承诺收敛，不承诺快。</span></p><p>LLM 的回合恰好是这个形态：一次完整 rollout 几百到几千 token，<a href="/llm/rlvr">可验证奖励</a>在序列末尾给一个判分——整段回报大结局才揭晓，整条 rollout 生成完才训练得动。语言模型上的 REINFORCE 一类序列级方法天然按蒙特卡洛记账，生成成本也因此成为训练成本的下界。这一课只做评估，控制（拿 \\(Q\\) 改策略）留给后两课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒙特卡洛只适用于有终止的回合制任务：持续任务没有 \\(T\\)，等不来大结局，这个缺口由下一课的 TD 接手。访问覆盖是前提：评估只覆盖被 \\(\\pi\\) 访问到的状态，上一课的 ε-贪婪是覆盖的保证，纯贪心会让没走过的格子永远停在初值。<span class="marginnote">常见误区：初学者容易以为「多跑几条回合就能补上没访问过的状态」。实际上蒙特卡洛是纯数据驱动的——回合没走到某个状态，那里就一个样本都没有，均值无从算起；跑再多回合也只是把走过的地方估得更准。这就是为什么探索（如 ε-贪婪）不是可选项，而是覆盖的前提。</span>不自举是双刃：蒙特卡洛不依赖其他状态的估计，误差不沿链传播，但同一回合里相邻状态的新信息也要各自等各自的样本，学不到「一半」。对 LLM 还有一步：结果奖励只在 EOS 出现时，过程中的对错完全不进账本——中期信号要等有了自举与优势的工具才用得上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无模型评估把 \\(v_\\pi\\) 换成经验回报的样本均值，转移模型缺席不再阻塞。</li><li>首次访问无偏，每次访问一致；增量形式 \\(V\\leftarrow V+\\alpha(G-V)\\)。</li><li>代价成对出现：高方差、必须等回合结束——整条余下轨迹的随机性折进一个数。</li><li>LLM 的 rollout 加结果奖励正是蒙特卡洛形态，生成完才训得动。</li><li>不自举免于误差传播，但也拿不到逐步信号；缺口由下一课的 TD(0) 接手。</li><li>出处：Sutton &amp; Barto, Reinforcement Learning: An Introduction, 2018, 第 5 章（首次/每次访问与收敛口径）。</li></ul>',6))])}const f=i(m,[["render",d]]);export{c as __pageData,f as default};
